.settings-sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 1rem;
    min-width: 220px;
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    height: 100%;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: none;
    background: none;
    border-radius: 0.5rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #495057;
    text-align: left;
    transition: background-color 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background-color: #e9ecef;
}

.sidebar-item.active {
