@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Profile Settings</h3>

    @if (isLoading)
    {
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success">@successMessage</div>
        }

        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(avatarUrl))
            {
                <img src="@avatarUrl" alt="Avatar" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
            <input type="text" class="form-control" placeholder="Avatar URL" @bind="avatarUrl" />
        </div>

        <div class="form-group mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="displayName" />
        </div>

        <div class="form-group mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="email" />
        </div>

        <div class="form-group mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="bio"></textarea>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" disabled="@(isLoading || isSaving)" @onclick="SaveAsync">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" disabled="@isLoading" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private bool isLoading = true;
    private bool isSaving;
    private string displayName = string.Empty;
    private string email = string.Empty;
    private string avatarUrl = string.Empty;
    private string bio = string.Empty;
    private string successMessage = string.Empty;
    private UserProfile? savedProfile;
    private CancellationTokenSource? successCts;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        ApplyProfile(profile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        avatarUrl = profile.AvatarUrl;
        bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        try
        {
            var profile = new UserProfile(displayName, email, avatarUrl, bio);
            await SettingsService.SaveProfileAsync(profile);
            savedProfile = profile;
            await ShowSuccessMessageAsync("Profile saved successfully.");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
    }

    private async Task ShowSuccessMessageAsync(string message)
    {
        successCts?.Cancel();
        successCts?.Dispose();
        successCts = new CancellationTokenSource();
        successMessage = message;

        try
        {
            await Task.Delay(3000, successCts.Token);
            successMessage = string.Empty;
        }
        catch (TaskCanceledException)
        {
            // Timer was cancelled; leave message as-is or cleared by next call
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (successCts is not null)
        {
            successCts.Cancel();
            successCts.Dispose();
            successCts = null;
        }

        await ValueTask.CompletedTask;
    }
}

