@using sv_9cd8dbbeca7248e59f40b2e490fb581b
@inject ISettingsService SettingsService
@implements IAsyncDisposable

<div class="settings-section">
    <h3>Appearance Settings</h3>

    @if (showSuccess)
    {
        <div class="alert alert-success">Appearance settings saved successfully!</div>
    }

    <div class="setting-group">
        <h5>Theme</h5>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="theme" id="themeLight" value="Light" @onchange="@(() => theme = "Light")" checked="@(theme == "Light")">
            <label class="form-check-label" for="themeLight">Light</label>
        </div>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="theme" id="themeDark" value="Dark" @onchange="@(() => theme = "Dark")" checked="@(theme == "Dark")">
            <label class="form-check-label" for="themeDark">Dark</label>
        </div>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="theme" id="themeSystem" value="System" @onchange="@(() => theme = "System")" checked="@(theme == "System")">
            <label class="form-check-label" for="themeSystem">System</label>
        </div>
    </div>

    <div class="setting-group">
        <h5>Font Size</h5>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="fontSize" id="fontSmall" value="Small" @onchange="@(() => fontSize = "Small")" checked="@(fontSize == "Small")">
            <label class="form-check-label" for="fontSmall">Small</label>
        </div>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="fontSize" id="fontMedium" value="Medium" @onchange="@(() => fontSize = "Medium")" checked="@(fontSize == "Medium")">
            <label class="form-check-label" for="fontMedium">Medium</label>
        </div>
        <div class="form-check form-check-inline">
            <input class="form-check-input" type="radio" name="fontSize" id="fontLarge" value="Large" @onchange="@(() => fontSize = "Large")" checked="@(fontSize == "Large")">
            <label class="form-check-label" for="fontLarge">Large</label>
        </div>
    </div>

    <div class="setting-group">
        <h5>Language</h5>
        <select class="form-select" @bind="language">
            <option>English</option>
            <option>Spanish</option>
            <option>French</option>
            <option>German</option>
            <option>Japanese</option>
        </select>
    </div>

    <div class="setting-group">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode">
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <div class="preview-area">
        <div class="card" style="@GetPreviewStyle()">
            <h6>Preview</h6>
            <p>This is how your content will look with the selected settings.</p>
            <button class="btn btn-primary btn-sm">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @(isSaving ? "Saving..." : "Save")
    </button>
</div>

@code {
    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private bool isSaving;
    private bool showSuccess;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
    }

    private string GetPreviewStyle()
    {
        var bg = theme switch
        {
            "Dark" => "#1a1a2e",
            "System" => "#f0f0f0",
            _ => "white"
        };

        var color = theme switch
        {
            "Dark" => "#e0e0e0",
            _ => "#333"
        };

        var fs = fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };

        var padding = compactMode ? "0.75rem" : "1.5rem";

        return $"background-color: {bg}; color: {color}; font-size: {fs}; padding: {padding};";
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        try
        {
            var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
            await SettingsService.SaveAppearanceAsync(settings);

            cts?.Cancel();
            cts?.Dispose();
            cts = new CancellationTokenSource();
            showSuccess = true;

            var token = cts.Token;
            _ = Task.Run(async () =>
            {
                try
                {
                    await Task.Delay(3000, token);
                    showSuccess = false;
                    await InvokeAsync(StateHasChanged);
                }
                catch (TaskCanceledException) { }
            });
        }
        finally
        {
            isSaving = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            cts.Cancel();
            cts.Dispose();
        }
    }
}

