@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (isLoading)
    {
        <div class="text-center p-3">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success">@successMessage</div>
        }

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="alert alert-danger">@errorMessage</div>
        }

        <!-- Change Password -->
        <div class="password-panel">
            <div class="section-header" @onclick="ToggleChangePassword">
                <h5>Change Password</h5>
                <button class="btn btn-link">@(showChangePassword ? "Collapse" : "Expand")</button>
            </div>

            @if (showChangePassword)
            {
                <div class="card p-3 mb-3">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm Password</label>
                        <input type="password" class="form-control" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="alert alert-danger">@passwordError</div>
                    }

                    <button class="btn btn-warning" @onclick="HandleChangePassword" disabled="@isSubmitting">
                        @(isSubmitting ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="mb-4">
            <h5>Two-Factor Authentication</h5>
            <div class="tfa-status">
                @if (twoFactorEnabled)
                {
                    <span class="badge bg-success">Enabled</span>
                }
                else
                {
                    <span class="badge bg-secondary">Disabled</span>
                }
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@twoFactorEnabled"
                           @onchange="ToggleTwoFactor" />
                    <label class="form-check-label">Enable 2FA</label>
                </div>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="text-muted">Last changed: @lastPasswordChange.Value.ToString("g")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div>
            <h5>Active Sessions</h5>
            <table class="table table-striped">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @for (int i = 0; i < sessions.Count; i++)
                    {
                        var index = i;
                        var session = sessions[index];
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (index == 0)
                                {
                                    <span class="badge bg-primary">Current</span>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>

            @if (!string.IsNullOrEmpty(sessionToRevoke))
            {
                var revokeSession = sessions.FirstOrDefault(s => s.Id == sessionToRevoke);
                if (revokeSession is not null)
                {
                    <div class="alert alert-warning">
                        <p>Are you sure you want to revoke this session on @revokeSession.Device?</p>
                        <button class="btn btn-danger btn-sm me-2" @onclick="HandleRevokeSession">Yes, Revoke</button>
                        <button class="btn btn-secondary btn-sm" @onclick="CancelRevoke">Cancel</button>
                    </div>
                }
            }
        </div>
    }
</div>

@code {
    private bool isLoading = true;
    private bool isSubmitting;
    private bool showChangePassword;
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();

    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;

    private string? passwordError;
    private string? successMessage;
    private string? errorMessage;
    private string? sessionToRevoke;

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        await LoadSecuritySettings();
    }

    private async Task LoadSecuritySettings()
    {
        try
        {
            isLoading = true;
            var settings = await SettingsService.GetSecuritySettingsAsync();
            twoFactorEnabled = settings.TwoFactorEnabled;
            lastPasswordChange = settings.LastPasswordChange;
            sessions = settings.Sessions ?? new();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load security settings: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleChangePassword()
    {
        showChangePassword = !showChangePassword;
        passwordError = null;
    }

    private async Task HandleChangePassword()
    {
        passwordError = null;

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirm password do not match.";
            return;
        }

        try
        {
            isSubmitting = true;
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);

            currentPassword = string.Empty;
            newPassword = string.Empty;
            confirmPassword = string.Empty;
            showChangePassword = false;

            await ShowSuccessMessage("Password updated successfully.");
        }
        catch (Exception ex)
        {
            passwordError = $"Failed to change password: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void ToggleTwoFactor(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session.Id;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task HandleRevokeSession()
    {
        if (string.IsNullOrEmpty(sessionToRevoke)) return;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke);
            sessionToRevoke = null;
            await LoadSecuritySettings();
            await ShowSuccessMessage("Session revoked successfully.");
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to revoke session: {ex.Message}";
        }
    }

    private async Task ShowSuccessMessage(string message)
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();

        successMessage = message;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, _cts.Token);
            successMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException)
        {
            // Timer was cancelled, ignore
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            _cts.Cancel();
            _cts.Dispose();
            _cts = null;
        }

        await ValueTask.CompletedTask;
    }
}

