                            checked="@mutedChannels.Contains(channel)"
                            @onchange="() => ToggleMuteChannel(channel)"
                            id="@($"channel-{channel}")">
                     <label class="form-check-label" for="@($"channel-{channel}")">@channel</label>
                 </div>
             }
         </div>

         <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
             @(isSaving ? "Saving..." : "Save Preferences")
         </button>
     }
 </div>

 @code {
     private NotificationPrefs? prefs;
     private bool emailNotifications;
     private bool pushNotifications;
     private bool weeklyDigest;
     private List<string> mutedChannels = new();
     private bool isSaving;
     private bool showSuccess;
     private CancellationTokenSource? cts;

     private readonly List<string> availableChannels = new()
     {
         "general", "announcements", "updates", "marketing", "alerts"
     };

     protected override async Task OnInitializedAsync()
     {
         prefs = await SettingsService.GetNotificationPrefsAsync();
         emailNotifications = prefs.EmailNotifications;
         pushNotifications = prefs.PushNotifications;
         weeklyDigest = prefs.WeeklyDigest;
         mutedChannels = new List<string>(prefs.MutedChannels);
     }

     private void ToggleMuteChannel(string channel)
     {
         if (mutedChannels.Contains(channel))
         {
             mutedChannels.Remove(channel);
         }
         else
         {
             mutedChannels.Add(channel);
         }
     }

     private async Task SaveAsync()
     {
         isSaving = true;
         var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, new List<string>(mutedChannels));
         await SettingsService.SaveNotificationPrefsAsync(updated);
         prefs = updated;
         isSaving = false;

         showSuccess = true;
         cts?.Cancel();
         cts?.Dispose();
         cts = new CancellationTokenSource();
         var token = cts.Token;

         _ = Task.Run(async () =>
         {
             try
             {
                 await Task.Delay(3000, token);
                 showSuccess = false;
                 await InvokeAsync(StateHasChanged);
             }
             catch (TaskCanceledException) { }
         });
     }

     public async ValueTask DisposeAsync()
     {
         if (cts is not null)
         {
             cts.Cancel();
             cts.Dispose();
             cts = null;
         }
     }
